import Foundation

public func authTokens(root: URL) throws -> Data {
    let board = try String(contentsOf: root.appending(path: "_design/canvas/AuthSignIn.dc.html"), encoding: .utf8)
    let bundle = try String(
        contentsOf: root.appending(path: "_design/canvas/ds/chronoflow/components/bundle.js"), encoding: .utf8)
    let data = try Data(contentsOf: root.appending(path: "_design/canvas/ds/chronoflow/tokens.json"))
    let json = try JSONSerialization.jsonObject(with: data) as! [String: Any]
    var code =
        "// Generated by Tools/TokenGen from auth boards, tokens.json and components. Do not edit.\nimport Foundation\nnonisolated public enum AuthTokens {\n"
    let rules = [
        ("gutter", "padding: 16px 16px 24px", 16), ("bottom", "padding: 16px 16px 24px", 24),
        ("touch", "height: 44px", 44), ("backGlyph", "width=\"22\"", 22),
        ("brandGap", "gap: 6px", 6), ("moon", "width=\"20\"", 20),
        ("headingMargin", "margin-top: 32px", 32), ("fieldGap", "gap: 8px", 8),
        ("cardPadding", "padding: 20px", 20), ("cardRadius", "border-radius: 26px", 26),
        ("cardGap", "gap: 14px", 14), ("footerGap", "margin-top: 12px", 12),
        ("footerHeight", "min-height: 48px", 48), ("bannerGap", "gap: 10px", 10),
        ("bannerVertical", "padding: 12px 14px", 12), ("bannerHorizontal", "padding: 12px 14px", 14),
        ("bannerRadius", "border-radius: 18px", 18), ("bannerGlyph", "width=\"18\"", 18),
        ("bannerIconTop", "margin-top: 1px", 1), ("icon", "width=\"16\"", 16),
    ]
    for (name, declaration, value) in rules {
        guard board.contains(declaration) else { throw GenerationError.invalid("Auth board changed: \(name)") }
        code += "public static var \(name): CGFloat { \(value) }\n"
    }
    for (group, name, token) in [
        ("spacing", "spacer", "space-6"), ("spacing", "inset", "space-3"),
        ("radius", "fieldRadius", "radius-md"), ("radius", "noticeRadius", "radius-2xl"),
    ] {
        let rows = (json[group] as! [String: Any])["tokens"] as! [[String: Any]]
        let value = rows.first { $0["name"] as? String == token }!["value"] as! String
        guard let number = Double(value.replacingOccurrences(of: "px", with: "")) else {
            throw GenerationError.invalid("Invalid auth metric \(token)")
        }
        code += "public static var \(name): CGFloat { \(number) }\n"
    }
    guard bundle.contains("focus-visible:ring-2"), bundle.contains("disabled:opacity-50"),
        bundle.contains("bg-card"), bundle.contains("rounded-2xl"), bundle.contains("h-9"),
        bundle.contains("mt-0.5 size-4"),
        board.contains("border: 1px solid"), board.contains("destructive) 10%"), board.contains("destructive) 35%")
    else { throw GenerationError.invalid("Auth component styles changed") }
    code +=
        "public static var noticeIconTop: CGFloat { 2 }; public static var borderWidth: CGFloat { 1 }; public static var focusWidth: CGFloat { 2 }; public static var disabledOpacity: Double { 0.5 }\n"
    for appearance in ["light", "dark"] {
        let shadow = ((json["shadow"] as! [String: Any])["tokens"] as! [[String: Any]])[0]["value"] as! [String: String]
        let values = shadow[appearance]!.split(separator: " ")
        let y = values[1].replacingOccurrences(of: "px", with: "")
        let blur = Double(values[2].replacingOccurrences(of: "px", with: ""))!
        let spread = values[3].replacingOccurrences(of: "px", with: "")
        code +=
            "public static var \(appearance)ShadowY: CGFloat { \(y) }; public static var \(appearance)ShadowRadius: CGFloat { \(blur / 2) }; public static var \(appearance)ShadowSpread: CGFloat { \(spread) }\n"
    }
    code += "}\n"
    code += "extension Typography {\n"
    for (name, face, size, line, tracking, relative) in [
        ("authBrand", "fraunces400Opsz20", 18, 24, 0.0, "title3"),
        ("authHeading", "fraunces400Opsz32", 36, 40, -0.36, "largeTitle"),
        ("authBody", "figtree400", 16, 24, 0.0, "body"),
        ("authLabel", "figtree500", 14, 20, 0.0, "subheadline"),
        ("authStrong", "figtree600", 14, 20, 0.0, "subheadline"),
        ("authHint", "figtree400", 14, 20, 0.0, "subheadline"),
        ("authMeta", "figtree400", 12, 16, 0.0, "caption"),
    ] {
        if name == "authBrand" || name == "authHeading" {
            guard board.contains("font-size: \(size)px; line-height: \(line)px") else {
                throw GenerationError.invalid("Auth typography changed: \(name)")
            }
        } else {
            let groups = (json["type"] as! [String: Any])["groups"] as! [[String: Any]]
            let styles = groups.flatMap { $0["styles"] as! [[String: Any]] }
            guard
                styles.contains(where: {
                    $0["fontSize"] as? String == "\(size)px" && $0["lineHeight"] as? String == "\(line)px"
                })
            else {
                throw GenerationError.invalid("Missing auth typography: \(name)")
            }
        }
        code +=
            "public static var \(name): Style { Style(face: .\(face), size: \(size), lineHeight: \(line), tracking: \(tracking), relativeTo: .\(relative)) }\n"
    }
    code += "}\n"
    return try formattedSwift(code, root: root)
}
